                int levelRequirement = Math.max(SpellEngineMod.config.spell_binding_level_requirement_min, levelRequirementDefault * SpellEngineMod.config.spell_binding_level_requirement_multiplier + SpellEngineMod.config.spell_binding_level_requirement_offset);
