                        this.slotsChanged(this.inventory);
                        world.playSound(null, pos, SpellEngineSounds.BIND_SPELL.soundEvent(), SoundSource.BLOCKS, 1.0f, world.random.nextFloat() * 0.1f + 0.9f);
